// Valor esperado vem do que foi enviado, nunca da própria resposta
const sent = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
const body = pm.response.json();

pm.test("status 201", () => pm.response.to.have.status(201));

pm.test("campos iguais aos enviados", () => {
  ["firstName", "lastName", "address", "city", "telephone"].forEach((field) => {
    pm.expect(body[field], field).to.eql(sent[field]);
  });
});

pm.test("id gerado é um número", () => {
  pm.expect(body.id).to.be.a("number");
});

pm.test("responde em menos de 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

// Usado pelos próximos requests do fluxo
pm.collectionVariables.set("ownerId", body.id);

// O corpo cru tem o texto {{ownerId}}; replaceIn troca pelo valor real
const sent = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
const body = pm.response.json();
const before = JSON.parse(pm.collectionVariables.get("ownerBefore"));

pm.test("status 201", () => pm.response.to.have.status(201));

pm.test("id da resposta é diferente do id enviado", () => {
  pm.expect(body.id).to.not.eql(sent.id);
});

pm.test("campos iguais aos enviados", () => {
  ["firstName", "lastName", "address", "city", "telephone"].forEach((field) => {
    pm.expect(body[field], field).to.eql(sent[field]);
  });
});

pm.test("responde em menos de 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

// O dono do id enviado não pode ter sido sobrescrito
pm.sendRequest(pm.environment.get("baseUrl") + "/owners/" + sent.id, (err, res) => {
  pm.test("dono do id enviado continua igual", () => {
    pm.expect(err).to.be.null;
    pm.expect(res.json()).to.eql(before);
  });
});

// Dono criado por este request, para apagar no fim do fluxo
pm.collectionVariables.set("existingIdOwnerId", body.id);

// Foto do dono antes do POST, para comparar depois
const url = pm.environment.get("baseUrl") + "/owners/" + pm.collectionVariables.get("ownerId");
pm.sendRequest(url, (err, res) => {
  if (err) throw err;
  if (res.code !== 200) {
    throw new Error("Dono " + pm.collectionVariables.get("ownerId") + " não existe (status " + res.code + "). Rode o CT-API-OWNERS-01 antes.");
  }
  pm.collectionVariables.set("ownerBefore", JSON.stringify(res.json()));
});

