// Nenhum dono pode ter nascido com o id enviado
pm.sendRequest(pm.environment.get("baseUrl") + "/owners/" + sent.id, (err, res) => {
  pm.test("nenhum dono foi criado com o id enviado", () => {
    pm.expect(err).to.be.null;
    pm.expect(res.code).to.eql(404);
  });
});

// Dono criado por este request, para apagar no fim do fluxo
pm.collectionVariables.set("missingIdOwnerId", body.id);

// URL já com o id real (ex.: http://localhost:9966/petclinic/api/owners/21)
const url = pm.variables.replaceIn(pm.request.url.toString());

// "Já removido" também é sucesso para uma limpeza
pm.test("dono apagado ou já removido (204 ou 404)", () => {
  pm.expect(pm.response.code).to.be.oneOf([204, 404]);
});

